PRAGMA foreign_keys = ON;

CREATE TABLE Member(memberNo INTEGER PRIMARY KEY, fullName TEXT NOT NULL CHECK(trim(fullName)<>''), email TEXT NOT NULL UNIQUE CHECK(trim(email)<>''), phone TEXT NOT NULL, mailingAddress TEXT NOT NULL, dateJoined TEXT NOT NULL CHECK(date(dateJoined)=dateJoined), status TEXT NOT NULL CHECK(status IN ('active','suspended','expired','closed')), expiryDate TEXT NOT NULL CHECK(date(expiryDate)=expiryDate AND expiryDate>=dateJoined));
CREATE TABLE Employee(employeeNo INTEGER PRIMARY KEY, fullName TEXT NOT NULL CHECK(trim(fullName)<>''), email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL, jobTitle TEXT NOT NULL CHECK(jobTitle IN ('librarian','event coordinator','cataloguer','administrator','library assistant')), hireDate TEXT NOT NULL CHECK(date(hireDate)=hireDate), employmentStatus TEXT NOT NULL CHECK(employmentStatus IN ('active','leave','terminated')), supervisorNo INTEGER REFERENCES Employee(employeeNo) ON UPDATE CASCADE ON DELETE SET NULL, CHECK(supervisorNo IS NULL OR supervisorNo<>employeeNo));
CREATE TABLE Creator(creatorID INTEGER PRIMARY KEY, creatorName TEXT NOT NULL CHECK(trim(creatorName)<>''));
CREATE TABLE MaterialType(typeName TEXT PRIMARY KEY, defaultLoanDays INTEGER NOT NULL CHECK(defaultLoanDays>0));
CREATE TABLE CatalogueItem(catalogueNo INTEGER PRIMARY KEY, title TEXT NOT NULL CHECK(trim(title)<>''), publisher TEXT NOT NULL, publicationYear INTEGER NOT NULL CHECK(publicationYear BETWEEN 1000 AND 2100), language TEXT NOT NULL, subject TEXT NOT NULL, description TEXT NOT NULL, standardID TEXT, typeName TEXT NOT NULL REFERENCES MaterialType(typeName) ON UPDATE CASCADE);
CREATE UNIQUE INDEX uq_catalogue_standard ON CatalogueItem(standardID) WHERE standardID IS NOT NULL;
CREATE TABLE CreatedBy(catalogueNo INTEGER NOT NULL REFERENCES CatalogueItem(catalogueNo) ON UPDATE CASCADE ON DELETE CASCADE, creatorID INTEGER NOT NULL REFERENCES Creator(creatorID) ON UPDATE CASCADE, PRIMARY KEY(catalogueNo,creatorID));
CREATE TABLE PeriodicalIssue(catalogueNo INTEGER NOT NULL REFERENCES CatalogueItem(catalogueNo) ON UPDATE CASCADE ON DELETE CASCADE, volume INTEGER NOT NULL CHECK(volume>0), issueNo INTEGER NOT NULL CHECK(issueNo>0), publicationDate TEXT NOT NULL CHECK(date(publicationDate)=publicationDate), PRIMARY KEY(catalogueNo,volume,issueNo));
CREATE TABLE LibraryUnit(unitID INTEGER PRIMARY KEY, catalogueNo INTEGER NOT NULL REFERENCES CatalogueItem(catalogueNo) ON UPDATE CASCADE, status TEXT NOT NULL CHECK(status IN ('available','on loan','reserved for processing','damaged','lost','withdrawn')));
CREATE TABLE PhysicalCopy(unitID INTEGER PRIMARY KEY REFERENCES LibraryUnit(unitID) ON UPDATE CASCADE ON DELETE CASCADE, barcode TEXT NOT NULL UNIQUE, shelfLocation TEXT NOT NULL, acquisitionDate TEXT NOT NULL CHECK(date(acquisitionDate)=acquisitionDate), condition TEXT NOT NULL CHECK(condition IN ('new','good','fair','damaged','lost')));
CREATE TABLE DigitalLicence(unitID INTEGER PRIMARY KEY REFERENCES LibraryUnit(unitID) ON UPDATE CASCADE ON DELETE CASCADE, licenceNo TEXT NOT NULL UNIQUE, accessURL TEXT NOT NULL CHECK(trim(accessURL)<>''), licenceLimit INTEGER NOT NULL CHECK(licenceLimit>0));
CREATE TABLE RepresentsIssue(unitID INTEGER PRIMARY KEY REFERENCES LibraryUnit(unitID) ON UPDATE CASCADE ON DELETE CASCADE, catalogueNo INTEGER NOT NULL, volume INTEGER NOT NULL, issueNo INTEGER NOT NULL, FOREIGN KEY(catalogueNo,volume,issueNo) REFERENCES PeriodicalIssue(catalogueNo,volume,issueNo) ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE Loan(loanID INTEGER PRIMARY KEY, memberNo INTEGER NOT NULL REFERENCES Member(memberNo) ON UPDATE CASCADE, unitID INTEGER NOT NULL REFERENCES LibraryUnit(unitID) ON UPDATE CASCADE, processedByEmployeeNo INTEGER REFERENCES Employee(employeeNo) ON UPDATE CASCADE ON DELETE SET NULL, borrowedAt TEXT NOT NULL CHECK(datetime(borrowedAt)=borrowedAt), dueAt TEXT NOT NULL CHECK(datetime(dueAt)=dueAt AND dueAt>borrowedAt), returnedAt TEXT CHECK(returnedAt IS NULL OR (datetime(returnedAt)=returnedAt AND returnedAt>=borrowedAt)));
CREATE TABLE Fine(fineID INTEGER PRIMARY KEY, loanID INTEGER NOT NULL REFERENCES Loan(loanID) ON UPDATE CASCADE, amount NUMERIC NOT NULL CHECK(amount>=0), assessedDate TEXT NOT NULL CHECK(datetime(assessedDate)=assessedDate), reason TEXT NOT NULL CHECK(trim(reason)<>''), paymentStatus TEXT NOT NULL CHECK(paymentStatus IN ('unpaid','paid','waived')), paymentDate TEXT CHECK(paymentDate IS NULL OR datetime(paymentDate)=paymentDate));
CREATE TABLE Room(roomNo INTEGER PRIMARY KEY, roomName TEXT NOT NULL, floor INTEGER NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), accessibility TEXT NOT NULL, availabilityStatus TEXT NOT NULL CHECK(availabilityStatus IN ('available','unavailable','maintenance')));
CREATE TABLE Event(eventNo INTEGER PRIMARY KEY, title TEXT NOT NULL CHECK(trim(title)<>''), eventType TEXT NOT NULL CHECK(eventType IN ('book club','author talk','workshop','art show','film screening','children program','community meeting')), description TEXT NOT NULL, startTime TEXT NOT NULL CHECK(datetime(startTime)=startTime), endTime TEXT NOT NULL CHECK(datetime(endTime)=endTime AND endTime>startTime), maximumAttendance INTEGER NOT NULL CHECK(maximumAttendance>0), status TEXT NOT NULL CHECK(status IN ('scheduled','cancelled','completed')), roomNo INTEGER NOT NULL REFERENCES Room(roomNo) ON UPDATE CASCADE, organizerEmployeeNo INTEGER NOT NULL REFERENCES Employee(employeeNo) ON UPDATE CASCADE);
CREATE TABLE Audience(audienceName TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE RecommendedFor(eventNo INTEGER NOT NULL REFERENCES Event(eventNo) ON UPDATE CASCADE ON DELETE CASCADE, audienceName TEXT NOT NULL REFERENCES Audience(audienceName) ON UPDATE CASCADE, PRIMARY KEY(eventNo,audienceName));
CREATE TABLE Registration(registrationID INTEGER PRIMARY KEY, eventNo INTEGER NOT NULL REFERENCES Event(eventNo) ON UPDATE CASCADE, memberNo INTEGER NOT NULL REFERENCES Member(memberNo) ON UPDATE CASCADE, registrationTime TEXT NOT NULL CHECK(datetime(registrationTime)=registrationTime), status TEXT NOT NULL CHECK(status IN ('registered','cancelled','attended','no-show')), attended INTEGER NOT NULL CHECK(attended IN (0,1)), UNIQUE(eventNo,memberNo));
CREATE TABLE ItemProposal(proposalNo INTEGER PRIMARY KEY, title TEXT NOT NULL, creator TEXT NOT NULL, materialType TEXT NOT NULL, publicationInformation TEXT NOT NULL, sourceType TEXT NOT NULL CHECK(sourceType IN ('member donation','member request','personnel purchase suggestion')), dateSubmitted TEXT NOT NULL CHECK(datetime(dateSubmitted)=dateSubmitted), condition TEXT, notes TEXT NOT NULL, decisionStatus TEXT NOT NULL CHECK(decisionStatus IN ('pending','under review','accepted','rejected')), decisionDate TEXT CHECK(decisionDate IS NULL OR (datetime(decisionDate)=decisionDate AND decisionDate>=dateSubmitted)), memberNo INTEGER REFERENCES Member(memberNo) ON UPDATE CASCADE, reviewerEmployeeNo INTEGER REFERENCES Employee(employeeNo) ON UPDATE CASCADE, CHECK(sourceType='personnel purchase suggestion' OR memberNo IS NOT NULL), CHECK((decisionStatus IN ('pending','under review') AND decisionDate IS NULL) OR (decisionStatus IN ('accepted','rejected') AND decisionDate IS NOT NULL AND reviewerEmployeeNo IS NOT NULL)));
CREATE TABLE ResultsIn(proposalNo INTEGER PRIMARY KEY REFERENCES ItemProposal(proposalNo) ON UPDATE CASCADE ON DELETE CASCADE, catalogueNo INTEGER NOT NULL UNIQUE REFERENCES CatalogueItem(catalogueNo) ON UPDATE CASCADE);
CREATE TABLE VolunteerApplication(applicationNo INTEGER PRIMARY KEY, memberNo INTEGER NOT NULL REFERENCES Member(memberNo) ON UPDATE CASCADE, applicationDate TEXT NOT NULL CHECK(datetime(applicationDate)=applicationDate), areaOfInterest TEXT NOT NULL, availability TEXT NOT NULL, skills TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','completed')), assignmentNotes TEXT, reviewerEmployeeNo INTEGER REFERENCES Employee(employeeNo) ON UPDATE CASCADE, eventNo INTEGER REFERENCES Event(eventNo) ON UPDATE CASCADE, CHECK(status='pending' OR reviewerEmployeeNo IS NOT NULL), CHECK(assignmentNotes IS NULL OR status IN ('approved','completed')));
CREATE TABLE HelpRequest(requestNo INTEGER PRIMARY KEY, memberNo INTEGER NOT NULL REFERENCES Member(memberNo) ON UPDATE CASCADE, category TEXT NOT NULL CHECK(category IN ('research','technology','account','collection','accessibility','other')), questionDescription TEXT NOT NULL CHECK(trim(questionDescription)<>''), submittedAt TEXT NOT NULL CHECK(datetime(submittedAt)=submittedAt), priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), status TEXT NOT NULL CHECK(status IN ('open','assigned','resolved','closed')), response TEXT, completedAt TEXT CHECK(completedAt IS NULL OR (datetime(completedAt)=completedAt AND completedAt>=submittedAt)), assignedEmployeeNo INTEGER REFERENCES Employee(employeeNo) ON UPDATE CASCADE, CHECK(status NOT IN ('resolved','closed') OR (response IS NOT NULL AND trim(response)<>'' AND completedAt IS NOT NULL AND assignedEmployeeNo IS NOT NULL)), CHECK(status<>'assigned' OR assignedEmployeeNo IS NOT NULL));

CREATE TRIGGER subtype_physical_insert BEFORE INSERT ON PhysicalCopy WHEN EXISTS(SELECT 1 FROM DigitalLicence WHERE unitID=NEW.unitID) BEGIN SELECT RAISE(ABORT,'unit already has digital subtype'); END;
CREATE TRIGGER subtype_physical_update BEFORE UPDATE OF unitID ON PhysicalCopy WHEN EXISTS(SELECT 1 FROM DigitalLicence WHERE unitID=NEW.unitID) BEGIN SELECT RAISE(ABORT,'unit already has digital subtype'); END;
CREATE TRIGGER subtype_digital_insert BEFORE INSERT ON DigitalLicence WHEN EXISTS(SELECT 1 FROM PhysicalCopy WHERE unitID=NEW.unitID) BEGIN SELECT RAISE(ABORT,'unit already has physical subtype'); END;
CREATE TRIGGER subtype_digital_update BEFORE UPDATE OF unitID ON DigitalLicence WHEN EXISTS(SELECT 1 FROM PhysicalCopy WHERE unitID=NEW.unitID) BEGIN SELECT RAISE(ABORT,'unit already has physical subtype'); END;
CREATE TRIGGER fine_dates_insert BEFORE INSERT ON Fine WHEN NEW.assessedDate < (SELECT borrowedAt FROM Loan WHERE loanID=NEW.loanID) OR (NEW.paymentDate IS NOT NULL AND NEW.paymentDate<NEW.assessedDate) BEGIN SELECT RAISE(ABORT,'invalid fine chronology'); END;
CREATE TRIGGER fine_dates_update BEFORE UPDATE ON Fine WHEN NEW.assessedDate < (SELECT borrowedAt FROM Loan WHERE loanID=NEW.loanID) OR (NEW.paymentDate IS NOT NULL AND NEW.paymentDate<NEW.assessedDate) BEGIN SELECT RAISE(ABORT,'invalid fine chronology'); END;
CREATE TRIGGER event_rules_insert BEFORE INSERT ON Event BEGIN SELECT CASE WHEN NEW.maximumAttendance>(SELECT capacity FROM Room WHERE roomNo=NEW.roomNo) THEN RAISE(ABORT,'event exceeds room capacity') WHEN NEW.status='scheduled' AND EXISTS(SELECT 1 FROM Event e WHERE e.roomNo=NEW.roomNo AND e.status='scheduled' AND NEW.startTime<e.endTime AND NEW.endTime>e.startTime) THEN RAISE(ABORT,'room event overlap') END; END;
CREATE TRIGGER event_rules_update BEFORE UPDATE ON Event BEGIN SELECT CASE WHEN NEW.maximumAttendance>(SELECT capacity FROM Room WHERE roomNo=NEW.roomNo) THEN RAISE(ABORT,'event exceeds room capacity') WHEN NEW.status='scheduled' AND EXISTS(SELECT 1 FROM Event e WHERE e.roomNo=NEW.roomNo AND e.eventNo<>OLD.eventNo AND e.status='scheduled' AND NEW.startTime<e.endTime AND NEW.endTime>e.startTime) THEN RAISE(ABORT,'room event overlap') END; END;
CREATE TRIGGER loan_rules_insert BEFORE INSERT ON Loan WHEN NEW.returnedAt IS NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM Member WHERE memberNo=NEW.memberNo AND status='active' AND expiryDate>=date(NEW.borrowedAt)) THEN RAISE(ABORT,'member is not active and unexpired') WHEN (SELECT count(*) FROM Loan WHERE memberNo=NEW.memberNo AND returnedAt IS NULL)>=5 THEN RAISE(ABORT,'active loan limit reached') WHEN EXISTS(SELECT 1 FROM Loan WHERE memberNo=NEW.memberNo AND returnedAt IS NULL AND dueAt<NEW.borrowedAt) THEN RAISE(ABORT,'member has overdue loan') WHEN COALESCE((SELECT sum(amount) FROM Fine f JOIN Loan l USING(loanID) WHERE l.memberNo=NEW.memberNo AND f.paymentStatus='unpaid'),0)>=20 THEN RAISE(ABORT,'unpaid fine limit reached') WHEN EXISTS(SELECT 1 FROM PhysicalCopy p JOIN Loan l ON l.unitID=p.unitID WHERE p.unitID=NEW.unitID AND l.returnedAt IS NULL) THEN RAISE(ABORT,'physical copy already loaned') WHEN EXISTS(SELECT 1 FROM PhysicalCopy WHERE unitID=NEW.unitID) AND (SELECT status FROM LibraryUnit WHERE unitID=NEW.unitID)<>'available' THEN RAISE(ABORT,'physical copy unavailable') WHEN EXISTS(SELECT 1 FROM DigitalLicence d WHERE d.unitID=NEW.unitID AND (SELECT count(*) FROM Loan l WHERE l.unitID=NEW.unitID AND l.returnedAt IS NULL)>=d.licenceLimit) THEN RAISE(ABORT,'digital licence limit reached') WHEN NOT EXISTS(SELECT 1 FROM PhysicalCopy WHERE unitID=NEW.unitID) AND NOT EXISTS(SELECT 1 FROM DigitalLicence WHERE unitID=NEW.unitID) THEN RAISE(ABORT,'unit has no subtype') END; END;
CREATE TRIGGER loan_rules_update BEFORE UPDATE ON Loan WHEN NEW.returnedAt IS NULL AND (OLD.returnedAt IS NOT NULL OR NEW.memberNo<>OLD.memberNo OR NEW.unitID<>OLD.unitID) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM Member WHERE memberNo=NEW.memberNo AND status='active' AND expiryDate>=date(NEW.borrowedAt)) THEN RAISE(ABORT,'member is not active and unexpired') WHEN (SELECT count(*) FROM Loan WHERE memberNo=NEW.memberNo AND returnedAt IS NULL AND loanID<>OLD.loanID)>=5 THEN RAISE(ABORT,'active loan limit reached') WHEN EXISTS(SELECT 1 FROM Loan WHERE memberNo=NEW.memberNo AND returnedAt IS NULL AND loanID<>OLD.loanID AND dueAt<NEW.borrowedAt) THEN RAISE(ABORT,'member has overdue loan') WHEN COALESCE((SELECT sum(amount) FROM Fine f JOIN Loan l USING(loanID) WHERE l.memberNo=NEW.memberNo AND f.paymentStatus='unpaid'),0)>=20 THEN RAISE(ABORT,'unpaid fine limit reached') WHEN EXISTS(SELECT 1 FROM PhysicalCopy p JOIN Loan l ON l.unitID=p.unitID WHERE p.unitID=NEW.unitID AND l.returnedAt IS NULL AND l.loanID<>OLD.loanID) THEN RAISE(ABORT,'physical copy already loaned') WHEN EXISTS(SELECT 1 FROM DigitalLicence d WHERE d.unitID=NEW.unitID AND (SELECT count(*) FROM Loan l WHERE l.unitID=NEW.unitID AND l.returnedAt IS NULL AND l.loanID<>OLD.loanID)>=d.licenceLimit) THEN RAISE(ABORT,'digital licence limit reached') END; END;
CREATE TRIGGER registration_rules_insert BEFORE INSERT ON Registration WHEN NEW.status='registered' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM Member WHERE memberNo=NEW.memberNo AND status='active' AND expiryDate>=date(NEW.registrationTime)) THEN RAISE(ABORT,'member not eligible') WHEN NOT EXISTS(SELECT 1 FROM Event WHERE eventNo=NEW.eventNo AND status='scheduled' AND startTime>NEW.registrationTime) THEN RAISE(ABORT,'event not open') WHEN (SELECT count(*) FROM Registration WHERE eventNo=NEW.eventNo AND status='registered') >= (SELECT maximumAttendance FROM Event WHERE eventNo=NEW.eventNo) THEN RAISE(ABORT,'event full') END; END;
CREATE TRIGGER registration_rules_update BEFORE UPDATE ON Registration WHEN NEW.status='registered' AND OLD.status<>'registered' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM Event WHERE eventNo=NEW.eventNo AND status='scheduled' AND startTime>NEW.registrationTime) THEN RAISE(ABORT,'event not open') WHEN (SELECT count(*) FROM Registration WHERE eventNo=NEW.eventNo AND status='registered' AND registrationID<>OLD.registrationID)>=(SELECT maximumAttendance FROM Event WHERE eventNo=NEW.eventNo) THEN RAISE(ABORT,'event full') END; END;
CREATE TRIGGER results_accepted_insert BEFORE INSERT ON ResultsIn WHEN NOT EXISTS(SELECT 1 FROM ItemProposal WHERE proposalNo=NEW.proposalNo AND decisionStatus='accepted') BEGIN SELECT RAISE(ABORT,'proposal not accepted'); END;

CREATE VIEW AvailableItems AS SELECT c.catalogueNo,c.title,c.typeName,u.unitID,u.status,p.shelfLocation,d.accessURL,d.licenceLimit FROM CatalogueItem c JOIN LibraryUnit u USING(catalogueNo) LEFT JOIN PhysicalCopy p USING(unitID) LEFT JOIN DigitalLicence d USING(unitID) WHERE (p.unitID IS NOT NULL AND u.status='available') OR (d.unitID IS NOT NULL AND u.status NOT IN ('withdrawn','lost') AND (SELECT count(*) FROM Loan l WHERE l.unitID=u.unitID AND l.returnedAt IS NULL)<d.licenceLimit);
CREATE VIEW ActiveLoans AS SELECT l.*,m.fullName,c.title FROM Loan l JOIN Member m USING(memberNo) JOIN LibraryUnit u USING(unitID) JOIN CatalogueItem c USING(catalogueNo) WHERE l.returnedAt IS NULL;
CREATE VIEW OverdueLoans AS SELECT * FROM ActiveLoans WHERE dueAt<datetime('now');
CREATE VIEW UnpaidFines AS SELECT f.*,l.memberNo FROM Fine f JOIN Loan l USING(loanID) WHERE f.paymentStatus='unpaid';
CREATE VIEW EventAvailability AS SELECT e.*,r.roomName,count(CASE WHEN g.status='registered' THEN 1 END) registrationCount,e.maximumAttendance-count(CASE WHEN g.status='registered' THEN 1 END) remainingCapacity FROM Event e JOIN Room r USING(roomNo) LEFT JOIN Registration g USING(eventNo) GROUP BY e.eventNo;
CREATE INDEX idx_catalogue_title ON CatalogueItem(title); CREATE INDEX idx_catalogue_subject ON CatalogueItem(subject); CREATE INDEX idx_catalogue_type ON CatalogueItem(typeName); CREATE INDEX idx_creator_name ON Creator(creatorName); CREATE INDEX idx_unit_catalogue_status ON LibraryUnit(catalogueNo,status); CREATE INDEX idx_loan_member_active ON Loan(memberNo) WHERE returnedAt IS NULL; CREATE INDEX idx_loan_unit_active ON Loan(unitID) WHERE returnedAt IS NULL; CREATE INDEX idx_event_start ON Event(startTime); CREATE INDEX idx_registration_event_status ON Registration(eventNo,status); CREATE INDEX idx_fine_loan_status ON Fine(loanID,paymentStatus);
